'use strict';
/**
 * When the studio is open.
 *
 * This did not exist, and an appointment was booked for 00:00-01:00 on a studio
 * that works 10:00-13:00. Nothing stopped it: the slot check asked the calendar
 * whether the time was free, and midnight is extremely free. Worse, when the
 * time a customer asked for was taken, the alternatives offered to him were
 * generated by walking from 00:00 in half-hour steps, so the bot proposed the
 * middle of the night by itself.
 *
 * The hours per professional are free text the owner types ("Mo-Fr 10-13"),
 * which is useful to read and impossible to enforce. This is the enforceable
 * version: one window for the studio, two settings, checked in code.
 *
 * It handles a window that crosses midnight (20:00-02:00), because a studio
 * that works evenings is normal and refusing its own opening hours would be a
 * worse bug than the one this fixes.
 *
 * No dependencies, so it can be tested without node_modules.
 */

const DAY = 24 * 60;

/** '10:00' -> 600. Anything else -> null. */
function parseHhmm(value) {
  const match = /^\s*(\d{1,2}):(\d{2})\s*$/.exec(String(value || ''));
  if (!match) return null;
  const h = Number(match[1]);
  const m = Number(match[2]);
  if (h > 23 || m > 59) return null;
  return h * 60 + m;
}

/** 600 -> '10:00'. */
function toHhmm(minutes) {
  const m = ((minutes % DAY) + DAY) % DAY;
  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
}

/**
 * The studio's open window, read from settings.
 *
 * Unreadable or equal values mean "no window set" rather than a window of
 * zero length: refusing every time of day because somebody typed the setting
 * wrong would take the whole studio off the air.
 *
 * @returns {{open:number, close:number, wraps:boolean, openText:string, closeText:string}|null}
 */
function readWindow(settings) {
  const open = parseHhmm(settings.get('studioOpenTime'));
  const close = parseHhmm(settings.get('studioCloseTime'));
  if (open === null || close === null || open === close) return null;
  return { open, close, wraps: close < open, openText: toHhmm(open), closeText: toHhmm(close) };
}

/**
 * Does an appointment of `durationMin` starting at `startTime` fit inside the
 * window, start to finish?
 *
 * The end matters as much as the start: a 90-minute massage beginning ten
 * minutes before closing is not a slot, it is an hour of unpaid overtime.
 */
function withinHours(startTime, durationMin, win) {
  if (!win) return true; // nothing configured: behave as before
  const start = parseHhmm(startTime);
  if (start === null) return false;
  const length = Number(durationMin) > 0 ? Number(durationMin) : 0;

  // A wrapping window runs open..close+24h; a time before `open` belongs to
  // the tail of that window, i.e. tomorrow morning in the same night's shift.
  const s = win.wraps && start < win.open ? start + DAY : start;
  const close = win.wraps ? win.close + DAY : win.close;
  return s >= win.open && s + length <= close;
}

/**
 * Every start time inside the window, in `stepMin` steps, that still leaves
 * room for the appointment. These are the only times the bot may ever offer.
 */
function candidateTimes(win, { stepMin = 30, durationMin = 0 } = {}) {
  if (!win) {
    // No window configured: the old behaviour, but at least a working day
    // rather than from midnight.
    const out = [];
    for (let m = 8 * 60; m + Number(durationMin || 0) <= 22 * 60; m += stepMin) out.push(toHhmm(m));
    return out;
  }
  const close = win.wraps ? win.close + DAY : win.close;
  const out = [];
  for (let m = win.open; m + Number(durationMin || 0) <= close; m += stepMin) out.push(toHhmm(m));
  return out;
}

/** For the model and the owner: "10:00-13:00". */
function describe(win) {
  return win ? `${win.openText}-${win.closeText}` : '';
}

module.exports = { parseHhmm, toHhmm, readWindow, withinHours, candidateTimes, describe, DAY };
